const fs = await import('node:fs/promises');
const P2 = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具";
const S = P2 + "\\_scripts";

// 核验所有交付文件
const check = async f => { try { const st = await fs.stat(f); return { f: f.split("\\").pop(), kb: Math.round(st.size/1024), ok: true }; } catch { return { f: f.split("\\").pop(), ok: false }; } };

const files = [
  P2+"\\接散活平台终版清单-71个.md",
  P2+"\\接散活平台书签-71个-终版.html",
  P2+"\\接单平台每日巡检表.md",
  S+"\\_GIG_FINAL_V2.json",
  S+"\\_CN_GIG_RESULT.json",
];
const results = [];
for (const f of files) results.push(await check(f));

// 核验平台数据完整性
const F = JSON.parse(await fs.readFile(S+"\\_GIG_FINAL_V2.json","utf8"));
const all = Object.values(F.groups).flat();
const tierCount = {};
for (const a of all) tierCount[a.tier]=(tierCount[a.tier]||0)+1;
const cnCount = (F.groups["🇨🇳 中文接单（实测）"]||[]).length;

// 核验书签格式
const bm = await fs.readFile(P2+"\\接散活平台书签-71个-终版.html","utf8");
const anchors = (bm.match(/<DT><A HREF=/g)||[]).length;

return {
  files: results,
  total: F.total,
  tiers: tierCount,
  cnPlatforms: cnCount,
  bookmarkLinks: anchors,
  bookmarkValid: bm.startsWith("<!DOCTYPE NETSCAPE-Bookmark-file-1>")
};
